        tuple[datetime, str, dict[str, Any]]
    ] = []

    for candidate in result_corpus:
        if candidate is source_result:
            continue

        candidate_job_id = str(
            candidate.get("job_id") or ""
        ).strip()

        if (
            source_job_id
            and candidate_job_id == source_job_id
        ):
            continue

