            candidate_completed
            or datetime.min.replace(
                tzinfo=timezone.utc
            )
        )

        preliminary.append(
            (
                sort_time,
                successor_sha,
                candidate,
            )
        )

    if not preliminary:
        return None

    preliminary.sort(
        key=lambda item: (
            item[0],
            item[1],
            str(
                item[2].get("job_id") or ""
            ),
        )
    )

    for _sort_time, successor_sha, candidate in preliminary:
        anchor_to_verify = (
            source_anchor
            or _valid_git_sha(
                candidate.get("execution_base_sha")
            )
            or _valid_git_sha(
                candidate.get("base_sha")
            )
        )

        if anchor_to_verify is None:
            continue

        if not _git_is_ancestor(
            anchor_to_verify,
            successor_sha,
