            successor_sha,
            current_head,
        ):
            continue

        changed = _target_diff_paths(
            anchor_to_verify,
            successor_sha,
            target_paths,
        )

        if changed is None:
            continue

        if not required_paths.issubset(changed):
            continue

        return candidate

    return None

